CREATE TABLE IF NOT EXISTS "accounts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Organisation name shown on branded join pages and invoices.
	"name" VARCHAR(160) NOT NULL,
	-- basic | pro | business | enterprise. Sets the meeting duration cap and the cloud recording allowance.
	"plan_tier" VARCHAR(20) NOT NULL DEFAULT 'basic',
	-- Licences purchased. Assigning more than this is what the provisioning check blocks.
	"seat_count" INTEGER NOT NULL DEFAULT 1,
	-- IANA timezone used when a host schedules without specifying one.
	"default_timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Cloud recording allowance in megabytes. Null means unmetered under an enterprise agreement.
	"storage_quota_mb" BIGINT,
	-- Account creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "accounts" IS 'The billing and policy boundary. Every user, licence and recording belongs to exactly one account, which is what makes retention and export a per-tenant operation.';
COMMENT ON COLUMN "accounts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "accounts"."name" IS 'Organisation name shown on branded join pages and invoices.';
COMMENT ON COLUMN "accounts"."plan_tier" IS 'basic | pro | business | enterprise. Sets the meeting duration cap and the cloud recording allowance.';
COMMENT ON COLUMN "accounts"."seat_count" IS 'Licences purchased. Assigning more than this is what the provisioning check blocks.';
COMMENT ON COLUMN "accounts"."default_timezone" IS 'IANA timezone used when a host schedules without specifying one.';
COMMENT ON COLUMN "accounts"."storage_quota_mb" IS 'Cloud recording allowance in megabytes. Null means unmetered under an enterprise agreement.';
COMMENT ON COLUMN "accounts"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning account.
	"account_id" BIGINT NOT NULL,
	-- Login identity, unique platform-wide.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Display name shown in the participant list when signed in.
	"full_name" VARCHAR(160) NOT NULL,
	-- The permanent room number. Null for a basic user who was never issued one; unique because it is dialled directly.
	"personal_meeting_id" VARCHAR(16) UNIQUE,
	-- IANA timezone. Scheduling stores instants, but the recurrence rule is expanded in this zone, which is what makes a weekly meeting survive a daylight-saving shift.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- member | admin | owner. Admins manage licences and recordings for the whole account.
	"role" VARCHAR(20) NOT NULL DEFAULT 'member',
	-- active | pending | deactivated. Deactivated users keep their recordings and hosted history.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- Row creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A person who can host or be invited. The timezone is on the user rather than the meeting because a recurrence rule only means something relative to a local calendar.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."account_id" IS 'Owning account.';
COMMENT ON COLUMN "users"."email" IS 'Login identity, unique platform-wide.';
COMMENT ON COLUMN "users"."full_name" IS 'Display name shown in the participant list when signed in.';
COMMENT ON COLUMN "users"."personal_meeting_id" IS 'The permanent room number. Null for a basic user who was never issued one; unique because it is dialled directly.';
COMMENT ON COLUMN "users"."timezone" IS 'IANA timezone. Scheduling stores instants, but the recurrence rule is expanded in this zone, which is what makes a weekly meeting survive a daylight-saving shift.';
COMMENT ON COLUMN "users"."role" IS 'member | admin | owner. Admins manage licences and recordings for the whole account.';
COMMENT ON COLUMN "users"."status" IS 'active | pending | deactivated. Deactivated users keep their recordings and hosted history.';
COMMENT ON COLUMN "users"."created_at" IS 'Row creation time.';

CREATE INDEX "idx_users_account_status"
ON "users" ("account_id", "status");

CREATE TABLE IF NOT EXISTS "licenses" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account that bought the licence.
	"account_id" BIGINT NOT NULL,
	-- Holder. Null for a purchased but unassigned seat, which is the state that makes seat counting a query rather than a guess.
	"assigned_user_id" BIGINT,
	-- licensed | webinar_500 | webinar_1000 | large_meeting | audio_conferencing. Add-ons are licences too.
	"kind" VARCHAR(24) NOT NULL,
	-- Capacity this licence grants. Copied onto the meeting at schedule time so downgrading later cannot shrink a booked event.
	"max_participants" INTEGER NOT NULL,
	-- Hard cap per meeting. Null means unlimited, which is what distinguishes a paid seat from a basic one.
	"max_duration_minutes" INTEGER,
	-- When the seat was given out. Null while unassigned.
	"assigned_at" TIMESTAMP,
	-- End of the entitlement period. Null for a perpetual grant.
	"expires_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "licenses" IS 'A seat, modelled as a row rather than a flag on the user. Unassigned rows exist, which is exactly how you count what was bought against what is in use.';
COMMENT ON COLUMN "licenses"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "licenses"."account_id" IS 'Account that bought the licence.';
COMMENT ON COLUMN "licenses"."assigned_user_id" IS 'Holder. Null for a purchased but unassigned seat, which is the state that makes seat counting a query rather than a guess.';
COMMENT ON COLUMN "licenses"."kind" IS 'licensed | webinar_500 | webinar_1000 | large_meeting | audio_conferencing. Add-ons are licences too.';
COMMENT ON COLUMN "licenses"."max_participants" IS 'Capacity this licence grants. Copied onto the meeting at schedule time so downgrading later cannot shrink a booked event.';
COMMENT ON COLUMN "licenses"."max_duration_minutes" IS 'Hard cap per meeting. Null means unlimited, which is what distinguishes a paid seat from a basic one.';
COMMENT ON COLUMN "licenses"."assigned_at" IS 'When the seat was given out. Null while unassigned.';
COMMENT ON COLUMN "licenses"."expires_at" IS 'End of the entitlement period. Null for a perpetual grant.';

CREATE INDEX "idx_licenses_account_kind_assignee"
ON "licenses" ("account_id", "kind", "assigned_user_id");
CREATE UNIQUE INDEX "uq_licenses_assigned_user"
ON "licenses" ("assigned_user_id");

CREATE TABLE IF NOT EXISTS "meetings" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning account, denormalised from the host so retention queries do not join through users.
	"account_id" BIGINT NOT NULL,
	-- Scheduler and default host.
	"host_user_id" BIGINT NOT NULL,
	-- Meeting title as invitees see it.
	"topic" VARCHAR(200) NOT NULL,
	-- Long-form description sent with the invitation.
	"agenda" TEXT,
	-- The dialable number. It belongs to the series, not the occurrence, which is why every instance of a weekly meeting shares one join link.
	"meeting_number" VARCHAR(16) NOT NULL UNIQUE,
	-- Hash of the join passcode. Null when the meeting relies on the waiting room instead.
	"passcode_hash" VARCHAR(255),
	-- RFC 5545 RRULE. Null for a one-off meeting - the single column that decides whether this row is a series or not.
	"recurrence_rule" VARCHAR(255),
	-- IANA zone the recurrence rule is expanded in. Without it a recurring 9am meeting drifts by an hour twice a year.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Planned length, used to generate each occurrence scheduled end.
	"duration_minutes" INTEGER NOT NULL,
	-- When true, joiners land in admissions rather than the meeting.
	"waiting_room_enabled" BOOLEAN NOT NULL DEFAULT true,
	-- Lets an occurrence start without the host connected.
	"join_before_host" BOOLEAN NOT NULL DEFAULT false,
	-- cloud | local. Null means recording is started manually.
	"auto_record" VARCHAR(16),
	-- When the meeting was scheduled.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "meetings" IS 'The series definition: identity, settings and the recurrence rule. It has no start time of its own - times belong to occurrences, even when there is only one.';
COMMENT ON COLUMN "meetings"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "meetings"."account_id" IS 'Owning account, denormalised from the host so retention queries do not join through users.';
COMMENT ON COLUMN "meetings"."host_user_id" IS 'Scheduler and default host.';
COMMENT ON COLUMN "meetings"."topic" IS 'Meeting title as invitees see it.';
COMMENT ON COLUMN "meetings"."agenda" IS 'Long-form description sent with the invitation.';
COMMENT ON COLUMN "meetings"."meeting_number" IS 'The dialable number. It belongs to the series, not the occurrence, which is why every instance of a weekly meeting shares one join link.';
COMMENT ON COLUMN "meetings"."passcode_hash" IS 'Hash of the join passcode. Null when the meeting relies on the waiting room instead.';
COMMENT ON COLUMN "meetings"."recurrence_rule" IS 'RFC 5545 RRULE. Null for a one-off meeting - the single column that decides whether this row is a series or not.';
COMMENT ON COLUMN "meetings"."timezone" IS 'IANA zone the recurrence rule is expanded in. Without it a recurring 9am meeting drifts by an hour twice a year.';
COMMENT ON COLUMN "meetings"."duration_minutes" IS 'Planned length, used to generate each occurrence scheduled end.';
COMMENT ON COLUMN "meetings"."waiting_room_enabled" IS 'When true, joiners land in admissions rather than the meeting.';
COMMENT ON COLUMN "meetings"."join_before_host" IS 'Lets an occurrence start without the host connected.';
COMMENT ON COLUMN "meetings"."auto_record" IS 'cloud | local. Null means recording is started manually.';
COMMENT ON COLUMN "meetings"."created_at" IS 'When the meeting was scheduled.';

CREATE INDEX "idx_meetings_host_created"
ON "meetings" ("host_user_id", "created_at");

CREATE TABLE IF NOT EXISTS "meeting_occurrences" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Series this instance belongs to.
	"meeting_id" BIGINT NOT NULL,
	-- Stable identifier of the instance within the series, derived from the original scheduled start. It survives a reschedule, which is what lets an invitation link keep resolving.
	"occurrence_key" VARCHAR(40) NOT NULL,
	-- Planned start as an instant. The local time is reconstructed with the meeting timezone rather than stored.
	"scheduled_start_at" TIMESTAMP NOT NULL,
	-- Planned end, materialised so calendar conflict queries are a range overlap.
	"scheduled_end_at" TIMESTAMP NOT NULL,
	-- scheduled | started | ended | cancelled. Cancelling one instance of a series changes this row only.
	"status" VARCHAR(20) NOT NULL DEFAULT 'scheduled',
	-- When the host actually started it. Null if it never ran, which is how a no-show is distinguished from a cancellation.
	"actual_start_at" TIMESTAMP,
	-- When the last participant left. Null while live.
	"actual_end_at" TIMESTAMP,
	-- Host for this instance when it differs from the series host. Null means inherit from the meeting.
	"host_user_id" BIGINT,
	-- Highest concurrent participant count, computed at end and stored so reporting never rescans the intervals.
	"participant_peak" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "meeting_occurrences" IS 'One row per instance, including for a one-off meeting. Everything that happens - participants, chat, recordings, admissions - points here, because those things happen at a time, not to a rule.';
COMMENT ON COLUMN "meeting_occurrences"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "meeting_occurrences"."meeting_id" IS 'Series this instance belongs to.';
COMMENT ON COLUMN "meeting_occurrences"."occurrence_key" IS 'Stable identifier of the instance within the series, derived from the original scheduled start. It survives a reschedule, which is what lets an invitation link keep resolving.';
COMMENT ON COLUMN "meeting_occurrences"."scheduled_start_at" IS 'Planned start as an instant. The local time is reconstructed with the meeting timezone rather than stored.';
COMMENT ON COLUMN "meeting_occurrences"."scheduled_end_at" IS 'Planned end, materialised so calendar conflict queries are a range overlap.';
COMMENT ON COLUMN "meeting_occurrences"."status" IS 'scheduled | started | ended | cancelled. Cancelling one instance of a series changes this row only.';
COMMENT ON COLUMN "meeting_occurrences"."actual_start_at" IS 'When the host actually started it. Null if it never ran, which is how a no-show is distinguished from a cancellation.';
COMMENT ON COLUMN "meeting_occurrences"."actual_end_at" IS 'When the last participant left. Null while live.';
COMMENT ON COLUMN "meeting_occurrences"."host_user_id" IS 'Host for this instance when it differs from the series host. Null means inherit from the meeting.';
COMMENT ON COLUMN "meeting_occurrences"."participant_peak" IS 'Highest concurrent participant count, computed at end and stored so reporting never rescans the intervals.';

CREATE UNIQUE INDEX "uq_occurrences_meeting_key"
ON "meeting_occurrences" ("meeting_id", "occurrence_key");
CREATE INDEX "idx_occurrences_schedule"
ON "meeting_occurrences" ("scheduled_start_at", "status");

CREATE TABLE IF NOT EXISTS "registrations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Instance registered for. Registering for a whole series creates one row per occurrence, so attendance is still countable per date.
	"occurrence_id" BIGINT NOT NULL,
	-- Registrant account, when they were signed in. Null for an external registrant who only gave an email.
	"user_id" BIGINT,
	-- Where the join link was sent. Always captured, even for signed-in users, because the link is the deliverable.
	"email" VARCHAR(320) NOT NULL,
	-- Name as typed on the registration form; it prefills the participant display name.
	"full_name" VARCHAR(160) NOT NULL,
	-- The personalised join link secret. Unique, so attendance can be attributed to a registrant without a login.
	"join_token" VARCHAR(64) NOT NULL UNIQUE,
	-- pending | approved | denied | cancelled. Pending exists when the host reviews registrations manually.
	"status" VARCHAR(16) NOT NULL DEFAULT 'approved',
	-- Submission time.
	"registered_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "registrations" IS 'Registration is per occurrence, not per series. That is what makes "who signed up for the 14th?" answerable and lets a single token be revoked for one date.';
COMMENT ON COLUMN "registrations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "registrations"."occurrence_id" IS 'Instance registered for. Registering for a whole series creates one row per occurrence, so attendance is still countable per date.';
COMMENT ON COLUMN "registrations"."user_id" IS 'Registrant account, when they were signed in. Null for an external registrant who only gave an email.';
COMMENT ON COLUMN "registrations"."email" IS 'Where the join link was sent. Always captured, even for signed-in users, because the link is the deliverable.';
COMMENT ON COLUMN "registrations"."full_name" IS 'Name as typed on the registration form; it prefills the participant display name.';
COMMENT ON COLUMN "registrations"."join_token" IS 'The personalised join link secret. Unique, so attendance can be attributed to a registrant without a login.';
COMMENT ON COLUMN "registrations"."status" IS 'pending | approved | denied | cancelled. Pending exists when the host reviews registrations manually.';
COMMENT ON COLUMN "registrations"."registered_at" IS 'Submission time.';

CREATE UNIQUE INDEX "uq_registrations_occurrence_email"
ON "registrations" ("occurrence_id", "email");
CREATE INDEX "idx_registrations_occurrence_status"
ON "registrations" ("occurrence_id", "status");

CREATE TABLE IF NOT EXISTS "participants" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Instance being attended.
	"occurrence_id" BIGINT NOT NULL,
	-- Signed-in account. Null for a guest who joined by link or phone.
	"user_id" BIGINT,
	-- Registration the join token came from, when there was one. Null for an open meeting.
	"registration_id" BIGINT,
	-- Name shown in the roster, captured at join time so renaming an account later does not rewrite the attendance report.
	"display_name" VARCHAR(160) NOT NULL,
	-- app | browser | phone | sip | room_system.
	"join_method" VARCHAR(16) NOT NULL DEFAULT 'app',
	-- Start of this attendance interval.
	"joined_at" TIMESTAMP NOT NULL,
	-- End of the interval. Null means still connected.
	"left_at" TIMESTAMP,
	-- left | removed | dropped | meeting_ended. Distinguishes a walkout from a bad connection.
	"leave_reason" VARCHAR(40),
	-- True for the interval during which this person held host controls; co-hosting and host handover both produce new intervals.
	"is_host" BOOLEAN NOT NULL DEFAULT false,
	-- Billable audio minutes for dial-in attendance. Null when audio came over the internet.
	"audio_minutes" INTEGER,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "participants" IS 'One row per join, not per person. A reconnect creates a second interval, which is why total attendance is a sum over intervals and concurrency is an overlap count.';
COMMENT ON COLUMN "participants"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "participants"."occurrence_id" IS 'Instance being attended.';
COMMENT ON COLUMN "participants"."user_id" IS 'Signed-in account. Null for a guest who joined by link or phone.';
COMMENT ON COLUMN "participants"."registration_id" IS 'Registration the join token came from, when there was one. Null for an open meeting.';
COMMENT ON COLUMN "participants"."display_name" IS 'Name shown in the roster, captured at join time so renaming an account later does not rewrite the attendance report.';
COMMENT ON COLUMN "participants"."join_method" IS 'app | browser | phone | sip | room_system.';
COMMENT ON COLUMN "participants"."joined_at" IS 'Start of this attendance interval.';
COMMENT ON COLUMN "participants"."left_at" IS 'End of the interval. Null means still connected.';
COMMENT ON COLUMN "participants"."leave_reason" IS 'left | removed | dropped | meeting_ended. Distinguishes a walkout from a bad connection.';
COMMENT ON COLUMN "participants"."is_host" IS 'True for the interval during which this person held host controls; co-hosting and host handover both produce new intervals.';
COMMENT ON COLUMN "participants"."audio_minutes" IS 'Billable audio minutes for dial-in attendance. Null when audio came over the internet.';

CREATE INDEX "idx_participants_occurrence_joined"
ON "participants" ("occurrence_id", "joined_at");
CREATE INDEX "idx_participants_user_joined"
ON "participants" ("user_id", "joined_at");

CREATE TABLE IF NOT EXISTS "waiting_room_admissions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Instance the person was waiting to enter.
	"occurrence_id" BIGINT NOT NULL,
	-- Name the joiner typed. Often the only thing the host has to decide on.
	"display_name" VARCHAR(160) NOT NULL,
	-- Signed-in account. Null for a guest, which is the case the waiting room exists for.
	"user_id" BIGINT,
	-- Participant row created on admission. Null while waiting or after a denial, which is what links the decision to the attendance.
	"participant_id" BIGINT,
	-- waiting | admitted | denied | expired.
	"decision" VARCHAR(16) NOT NULL DEFAULT 'waiting',
	-- Host or co-host who acted. Null when the meeting ended before anyone did.
	"decided_by_user_id" BIGINT,
	-- When they knocked.
	"requested_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When the host acted. The gap to requested_at is the number hosts complain about.
	"decided_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "waiting_room_admissions" IS 'The knock queue, kept after the meeting. It is the only record of who tried to join and was refused, which participants alone can never show.';
COMMENT ON COLUMN "waiting_room_admissions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "waiting_room_admissions"."occurrence_id" IS 'Instance the person was waiting to enter.';
COMMENT ON COLUMN "waiting_room_admissions"."display_name" IS 'Name the joiner typed. Often the only thing the host has to decide on.';
COMMENT ON COLUMN "waiting_room_admissions"."user_id" IS 'Signed-in account. Null for a guest, which is the case the waiting room exists for.';
COMMENT ON COLUMN "waiting_room_admissions"."participant_id" IS 'Participant row created on admission. Null while waiting or after a denial, which is what links the decision to the attendance.';
COMMENT ON COLUMN "waiting_room_admissions"."decision" IS 'waiting | admitted | denied | expired.';
COMMENT ON COLUMN "waiting_room_admissions"."decided_by_user_id" IS 'Host or co-host who acted. Null when the meeting ended before anyone did.';
COMMENT ON COLUMN "waiting_room_admissions"."requested_at" IS 'When they knocked.';
COMMENT ON COLUMN "waiting_room_admissions"."decided_at" IS 'When the host acted. The gap to requested_at is the number hosts complain about.';

CREATE INDEX "idx_admissions_occurrence_decision"
ON "waiting_room_admissions" ("occurrence_id", "decision");

CREATE TABLE IF NOT EXISTS "breakout_rooms" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Instance the rooms belong to. Breakouts are never reused across dates.
	"occurrence_id" BIGINT NOT NULL,
	-- Room name shown to participants, e.g. "Room 3" or a renamed topic.
	"name" VARCHAR(120) NOT NULL,
	-- Ordering in the host panel; assignment algorithms distribute round-robin over it.
	"room_index" SMALLINT NOT NULL,
	-- When the host opened the rooms. Null for a room that was configured but never opened.
	"opened_at" TIMESTAMP,
	-- When everyone was pulled back to the main room.
	"closed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "breakout_rooms" IS 'A sub-room of one occurrence. Pre-assignment before the meeting starts is why opened_at is nullable - the rows exist before the room does.';
COMMENT ON COLUMN "breakout_rooms"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "breakout_rooms"."occurrence_id" IS 'Instance the rooms belong to. Breakouts are never reused across dates.';
COMMENT ON COLUMN "breakout_rooms"."name" IS 'Room name shown to participants, e.g. "Room 3" or a renamed topic.';
COMMENT ON COLUMN "breakout_rooms"."room_index" IS 'Ordering in the host panel; assignment algorithms distribute round-robin over it.';
COMMENT ON COLUMN "breakout_rooms"."opened_at" IS 'When the host opened the rooms. Null for a room that was configured but never opened.';
COMMENT ON COLUMN "breakout_rooms"."closed_at" IS 'When everyone was pulled back to the main room.';

CREATE UNIQUE INDEX "uq_breakout_rooms_occurrence_index"
ON "breakout_rooms" ("occurrence_id", "room_index");

CREATE TABLE IF NOT EXISTS "breakout_room_members" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Room entered.
	"breakout_room_id" BIGINT NOT NULL,
	-- Attendance interval that entered it. Pointing at the participant rather than the user is what keeps a reconnect from confusing the record.
	"participant_id" BIGINT NOT NULL,
	-- When they arrived in the room.
	"entered_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When they left or were recalled. Null means still inside.
	"exited_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "breakout_room_members" IS 'Another interval table, because people are moved between rooms mid-session. A single room_id column on participants could not express being in two rooms across one meeting.';
COMMENT ON COLUMN "breakout_room_members"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "breakout_room_members"."breakout_room_id" IS 'Room entered.';
COMMENT ON COLUMN "breakout_room_members"."participant_id" IS 'Attendance interval that entered it. Pointing at the participant rather than the user is what keeps a reconnect from confusing the record.';
COMMENT ON COLUMN "breakout_room_members"."entered_at" IS 'When they arrived in the room.';
COMMENT ON COLUMN "breakout_room_members"."exited_at" IS 'When they left or were recalled. Null means still inside.';

CREATE INDEX "idx_breakout_members_room_entered"
ON "breakout_room_members" ("breakout_room_id", "entered_at");
CREATE INDEX "idx_breakout_members_participant"
ON "breakout_room_members" ("participant_id");

CREATE TABLE IF NOT EXISTS "recordings" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Instance recorded. A series has no recording; its individual dates do.
	"occurrence_id" BIGINT NOT NULL,
	-- Who pressed record. Null once that account is deleted; the file stays with the account.
	"started_by_user_id" BIGINT,
	-- cloud | local. Local recordings have metadata here but no object_url.
	"storage" VARCHAR(16) NOT NULL DEFAULT 'cloud',
	-- video | audio_only | transcript | chat_log. One row per artefact, because a single session emits several files.
	"kind" VARCHAR(20) NOT NULL,
	-- Object-store URL. Null for a local recording or one still processing.
	"object_url" VARCHAR(500),
	-- File size, counted against the account storage quota. Null until processing finishes.
	"size_bytes" BIGINT,
	-- Playback length. Null until processing finishes.
	"duration_seconds" INTEGER,
	-- Hash of the share passcode. Null when the link is open to the account.
	"passcode_hash" VARCHAR(255),
	-- processing | ready | failed | deleted.
	"status" VARCHAR(16) NOT NULL DEFAULT 'processing',
	-- When recording began, which is usually after the meeting started.
	"started_at" TIMESTAMP NOT NULL,
	-- Auto-deletion time under the account retention policy. Null means keep indefinitely.
	"expires_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "recordings" IS 'One row per artefact per occurrence. Pausing and resuming produces several rows rather than one gappy file, which is what keeps duration honest.';
COMMENT ON COLUMN "recordings"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "recordings"."occurrence_id" IS 'Instance recorded. A series has no recording; its individual dates do.';
COMMENT ON COLUMN "recordings"."started_by_user_id" IS 'Who pressed record. Null once that account is deleted; the file stays with the account.';
COMMENT ON COLUMN "recordings"."storage" IS 'cloud | local. Local recordings have metadata here but no object_url.';
COMMENT ON COLUMN "recordings"."kind" IS 'video | audio_only | transcript | chat_log. One row per artefact, because a single session emits several files.';
COMMENT ON COLUMN "recordings"."object_url" IS 'Object-store URL. Null for a local recording or one still processing.';
COMMENT ON COLUMN "recordings"."size_bytes" IS 'File size, counted against the account storage quota. Null until processing finishes.';
COMMENT ON COLUMN "recordings"."duration_seconds" IS 'Playback length. Null until processing finishes.';
COMMENT ON COLUMN "recordings"."passcode_hash" IS 'Hash of the share passcode. Null when the link is open to the account.';
COMMENT ON COLUMN "recordings"."status" IS 'processing | ready | failed | deleted.';
COMMENT ON COLUMN "recordings"."started_at" IS 'When recording began, which is usually after the meeting started.';
COMMENT ON COLUMN "recordings"."expires_at" IS 'Auto-deletion time under the account retention policy. Null means keep indefinitely.';

CREATE INDEX "idx_recordings_occurrence_kind"
ON "recordings" ("occurrence_id", "kind");
CREATE INDEX "idx_recordings_expiry"
ON "recordings" ("expires_at");

CREATE TABLE IF NOT EXISTS "meeting_chat_messages" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Instance the chat happened in. Chat never spans occurrences, which is why it hangs here and not off the meeting.
	"occurrence_id" BIGINT NOT NULL,
	-- The attendance interval that sent it, so a message keeps the display name that was on screen at the time.
	"sender_participant_id" BIGINT NOT NULL,
	-- Target of a direct message. Null for a message to everyone - that null is the entire visibility rule.
	"recipient_participant_id" BIGINT,
	-- Message text.
	"body" VARCHAR(2000) NOT NULL,
	-- Send time, the sole ordering key.
	"sent_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "meeting_chat_messages" IS 'In-meeting chat, scoped to one occurrence and discarded with it under retention. A null recipient means everyone, which keeps private and public messages in one ordered stream.';
COMMENT ON COLUMN "meeting_chat_messages"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "meeting_chat_messages"."occurrence_id" IS 'Instance the chat happened in. Chat never spans occurrences, which is why it hangs here and not off the meeting.';
COMMENT ON COLUMN "meeting_chat_messages"."sender_participant_id" IS 'The attendance interval that sent it, so a message keeps the display name that was on screen at the time.';
COMMENT ON COLUMN "meeting_chat_messages"."recipient_participant_id" IS 'Target of a direct message. Null for a message to everyone - that null is the entire visibility rule.';
COMMENT ON COLUMN "meeting_chat_messages"."body" IS 'Message text.';
COMMENT ON COLUMN "meeting_chat_messages"."sent_at" IS 'Send time, the sole ordering key.';

CREATE INDEX "idx_meeting_chat_occurrence_sent"
ON "meeting_chat_messages" ("occurrence_id", "sent_at");

